<?php $title='Configurações'; ?><section class="page-head"><div><h1>Configurações gerais</h1><p>Identidade, endereços, manutenção e limites da plataforma.</p></div><a class="btn" href="<?= e(base_url('perfil')) ?>">Segurança do perfil</a></section><form class="panel form-grid" method="post" action="<?= e(base_url('configuracoes')) ?>" data-loading><?= csrf_field() ?><label>Nome da plataforma *<input name="platform_name" value="<?= e($settings['platform_name']??'') ?>" required></label><label>URL da aplicação *<input type="url" name="app_url" value="<?= e($settings['app_url']??'') ?>" required></label><label>Nome da empresa<input name="company_name" value="<?= e($settings['company_name']??'') ?>"></label><label>E-mail administrativo *<input type="email" name="admin_email" value="<?= e($settings['admin_email']??'') ?>" required></label><label>Fuso horário<input name="timezone" value="<?= e($settings['timezone']??'America/Bahia') ?>"></label><label>URL pública do Caixas *<input type="url" name="caixas_url" value="<?= e($settings['caixas_url']??'https://caixas.gda.app.br') ?>" required></label><label>URL administrativa do Caixas *<input type="url" name="caixas_admin_url" value="<?= e($settings['caixas_admin_url']??'https://caixas.gda.app.br/admin-gda') ?>" required></label><label>Limite de atualização (MB)<input type="number" min="1" max="500" name="max_update_mb" value="<?= e($settings['max_update_mb']??'50') ?>"></label><label>Modo manutenção<select name="maintenance_mode"><option value="0" <?= ($settings['maintenance_mode']??'0')==='0'?'selected':'' ?>>Desativado</option><option value="1" <?= ($settings['maintenance_mode']??'0')==='1'?'selected':'' ?>>Ativado</option></select></label><label class="full">Mensagem de manutenção<textarea name="maintenance_message"><?= e($settings['maintenance_message']??'') ?></textarea></label><div class="form-actions full"><button class="btn primary">Salvar configurações</button></div></form>
<section class="panel"><h2>Diagnóstico do sistema</h2><div class="diagnostic"><?php foreach(['PHP '.$diagnostic['php']=>$diagnostic['php_ok'],'Extensão PDO'=>$diagnostic['pdo'],'Driver PDO MySQL'=>$diagnostic['pdo_mysql'],'Extensão ZIP'=>$diagnostic['zip'],'Conexão com o banco'=>$diagnostic['db']] as $label=>$ok): ?><div><span><?= e($label) ?></span><b class="<?= $ok?'ok':'bad' ?>"><?= $ok?'Disponível':'Indisponível' ?></b></div><?php endforeach; ?><div><span>Upload máximo</span><b><?= e($diagnostic['upload_max']) ?> / POST <?= e($diagnostic['post_max']) ?></b></div><div><span>Versão da aplicação</span><b><?= e($diagnostic['version']) ?></b></div><?php foreach($diagnostic['folders'] as $folder=>$ok): ?><div><span><?= e($folder) ?></span><b class="<?= $ok?'ok':'bad' ?>"><?= $ok?'Gravável':'Sem permissão' ?></b></div><?php endforeach; ?></div></section>
